@Finsupp.mapDomain_support_of_injOn : ∀ {α : Type u_1} {β : Type u_2} {M : Type u_3} [inst : AddCommMonoid M]
  [inst_1 : DecidableEq β] {f : α → β} (s : α →₀ M),
  Set.InjOn f ↑s.support → (Finsupp.mapDomain f s).support = Finset.image f s.support

@LinearIndependent.map_injOn : ∀ {ι : Type u_1} {R : Type u_2} {M : Type u_3} {M' : Type u_4} {v : ι → M}
  [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : AddCommMonoid M'] [inst_3 : Module R M]
  [inst_4 : Module R M'],
  LinearIndependent R v →
    ∀ (f : M →ₗ[R] M'), Set.InjOn ⇑f ↑(Submodule.span R (Set.range v)) → LinearIndependent R (⇑f ∘ v)

@LinearMap.linearIndependent_iff_of_injOn : ∀ {ι : Type u_1} {R : Type u_2} {M : Type u_3} {M' : Type u_4} {v : ι → M}
  [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : AddCommMonoid M'] [inst_3 : Module R M]
  [inst_4 : Module R M'] (f : M →ₗ[R] M'),
  Set.InjOn ⇑f ↑(Submodule.span R (Set.range v)) → (LinearIndependent R (⇑f ∘ v) ↔ LinearIndependent R v)

@LinearIndependent.map' : ∀ {ι : Type u_1} {R : Type u_2} {M : Type u_3} {M' : Type u_4} {v : ι → M} [inst : Ring R]
  [inst_1 : AddCommGroup M] [inst_2 : AddCommGroup M'] [inst_3 : Module R M] [inst_4 : Module R M'],
  LinearIndependent R v → ∀ (f : M →ₗ[R] M'), f.ker = ⊥ → LinearIndependent R (⇑f ∘ v)

@AddMonoidAlgebra.mem_supported : ∀ {R : Type u_1} {S : Type u_2} {M : Type u_3} [inst : Semiring R]
  [inst_1 : Semiring S] [inst_2 : Module R S] {s : Set M} {x : AddMonoidAlgebra S M},
  x ∈ AddMonoidAlgebra.supported R S s ↔ ↑x.coeff.support ⊆ s

@Submodule.mem_span_image_iff_exists_fun : ∀ {α : Type u_1} {M : Type u_2} (R : Type u_3) [inst : Semiring R]
  [inst_1 : AddCommMonoid M] [inst_2 : Module R M] {v : α → M} {x : M} {s : Set α},
  x ∈ Submodule.span R (v '' s) ↔ ∃ t, ↑t ⊆ s ∧ ∃ c, ∑ i, c i • v ↑i = x

@Submodule.mem_span_image_finset_iff_exists_fun' : ∀ {α : Type u_1} {M : Type u_2} (R : Type u_3) [inst : Semiring R]
  [inst_1 : AddCommMonoid M] [inst_2 : Module R M] {v : α → M} {x : M} {s : Finset α},
  x ∈ Submodule.span R (v '' ↑s) ↔ ∃ c, ∑ i ∈ s, c i • v i = x
